// Liste des SIREN des clients et fournisseurs (300 au maximum) envoyés aux API publiques de l'État
const noeuds = ["Pennylane · Clients"];
const vus = {};
noeuds.forEach((n) => { let pages = []; try { pages = $(n).all(); } catch (e) { pages = []; } pages.forEach((p) => (p.json.items || []).forEach((t) => { const s = String(t.reg_no || '').replace(/\D/g, ''); if (s.length === 9) vus[s] = true; })); });
const liste = Object.keys(vus).slice(0, 300);
return (liste.length ? liste : ['000000000']).map((siren) => ({ json: { siren } }));

