    return best;
  }

  function lireCSV(txt) {
    txt = String(txt || '').replace(/^﻿/, '');
    var premiere = txt.split(/\r?\n/).find(function (l) { return l.trim(); }) || '';
    var sep = detecterSeparateur(premiere), rows = [], row = [], cell = '', q = false;
    for (var i = 0; i < txt.length; i++) {
